public static int findNthLeapYear(int Y, int N) {
  if (Y < 0) return -1;
  if (N < 0) return -1;

  Queue<Integer> que = new LinkedList<>();
  for (int i = 0; i <= 9; i++) {
    que.offer(i);
  }

  int count = 0;

  while (!que.isEmpty()) {
    int num = que.poll();
    if (count++ == N) {
      return num;
    }
    int lastDigit = num % 4;
    if (lastDigit > 0) {
      que.offer(num + 1);
    }
    if (lastDigit < 3) {
      que.offer(num - 1);
    }
  }

  return -1;
}

