public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> results = new ArrayList<>();
    if (nums.length == 1) {
        results.add(Arrays.asList(nums));
        return results;
    }
    for (int i = 0; i < nums.length; i++) {
        int num = nums[i];
        List<List<Integer>> subresults = permute(Arrays.copyOfRange(nums, 0, i) + Arrays.copyOfRange(nums, i + 1, nums.length));
        for (List<Integer> subresult : subresults) {
            subresult.add(0, num);
        }
        results.addAll(subresults);
    }
    return results;
}
