    int maxSubstring = 0;
    for (int i = 0; i < str.length(); i++) {
        for (int j = i; j < str.length(); j++) {
            String substring = str.substring(i, j + 1);
            if (str.contains(substring) || str.toLowerCase().contains(substring.toLowerCase())) {
