  public static int countOilDeposits(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
      for (int j = 0; j < grid[i].length; j++) {
        if (grid[i][j] == '@') {
          // Check if this is a new oil deposit
          if (isOilDeposit(grid, i, j)) {
            count++;
          }
        }
      }
    }
    return count;
  }

  /**
   * Checks if a given point is the start of an oil deposit.
   * @param grid The grid representing the land.
   * @param i The row index of the point to check.
   * @param j The column index of the point to check.
   * @return True if the point is the start of an oil deposit, false otherwise.
   */
  private static boolean isOilDeposit(char[][] grid, int i, int j) {
    // Check if the point is an oil deposit
    if (grid[i][j] != '@') {
      return false;
    }

    // Check if the point is surrounded by water
    if (i > 0 && grid[i - 1][j] == '*') {
      return true;
    }
    if (i < grid.length - 1 && grid[i + 1][j] == '*') {
      return true;
    }
    if (j > 0 && grid[i][j - 1] == '*') {
      return true;
    }
    if (j < grid[i].length - 1 && grid[i][j + 1] == '*') {
      return true;
    }
    return false;
  }
}

