public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the start and end points are within the boundaries of the maze
    if (start[0] < 0 || start[1] < 0 || end[0] >= n || end[1] >= n) {
        return "cannot be travelled";
    }

    // Check if there are any paths between the start and end points
    for (int[] path : paths) {
        if (start[0] == path[0] && start[1] == path[1]) {
            return "cannot be travelled";
        }
        if (end[0] == path[0] && end[1] == path[1]) {
            return "can be travelled";
        }
    }

    return "cannot be travelled";
}
