public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the starting and ending coordinates are within the bounds of the maze
    if (start[0] < 0 || start[1] < 0 || end[0] >= n || end[1] >= n) {
        return "cannot be travelled";
    }

    // Create a hash set to keep track of the visited n-tersections
    HashSet<int[]> visited = new HashSet<>();

    // Create a queue to keep track of the n-tersections to be visited
    Queue<int[]> queue = new LinkedList<>();

    // Add the starting n-tersection to the queue
    queue.add(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection from the queue
        int[] current = queue.remove();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        // Mark the current n-tersection as visited
        visited.add(current);

        // Get the neighbors of the current n-tersection
        int[][] neighbors = getNeighbors(current);

        // Add the unvisited neighbors to the queue
        for (int[] neighbor : neighbors) {
            if (!visited.contains(neighbor) && !queue.contains(neighbor)) {
                queue.add(neighbor);
            }
        }
    }

    // If the queue is empty, return "cannot be travelled"
    return "cannot be travelled";
}

private static int[][] getNeighbors(int[] current) {
    int[][] neighbors = new int[4][2];
    // Get the neighbors of the current n-tersection
    for (int i = 0; i < 4; i++) {
        int row = current[0] + (i / 2) - 1;
        int col = current[1] + (i % 2) - 1;

        // If the row or column is out of bounds, skip this neighbor
        if (row < 0 || row >= n || col < 0 || col >= n) {
            continue;
        }

        // Add the neighbor to the list of neighbors
        neighbors[i] = new int[]{row, col};
    }
    return neighbors;
}
