public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {

  // Create a hash set to keep track of visited n-intersections
  HashSet<String> visited = new HashSet<>();

  // Add the starting n-terestcing to the hash set
  String startPoint = getPoint(n, start[0], start[1]);
  visited.add(startPoint);

  // Create a queue to store the n-intersections to visit
  Queue<String> toVisit = new LinkedList<>();
  toVisit.add(startPoint);

  // Create a queue to store the paths to visit
  Queue<int[][]> pathsToVisit = new LinkedList<>();
  pathsToVisit.add(paths);

  // Loop until all n-intersections have been visited
  while (!toVisit.isEmpty()) {

    // Get the current n-terestcing and adjacent n-intersections
    String current = toVisit.remove();
    int[][] currentPaths = pathsToVisit.remove();

    // Check if the current n-terestcing is the ending n-terestcing
    if (current.equals(getPoint(n, end[0], end[1]))) {
      return "can be travelled";
    }

    // Mark the current n-terestcing as visited
    visited.add(current);

    // Get the adjacent n-intersections and paths
    List<String> adjacentIntersections = getAdjacentIntersections(n, current);
    List<int[][]> adjacentPaths = getAdjacentPaths(currentPaths, adjacentIntersections);

    // Add the adjacent n-intersections and paths to the queue
    for (int i = 0; i < adjacentIntersections.size(); i++) {
      toVisit.add(adjacentIntersections.get(i));
      pathsToVisit.add(adjacentPaths.get(i));
    }
  }

  // If all n-intersections have been visited and the ending n-terestcing has not been found, return that travel is not possible
  return "cannot be travelled";
}

private static String getPoint(int n, int x, int y) {
  return x + "," + y;
}

private static List<String> getAdjacentIntersections(int n, String current) {
  // Split the current n-terestcing coordinates
  String[] coord = current.split(",");
  int x = Integer.parseInt(coord[0]);
  int y = Integer.parseInt(coord[1]);

  // Get the adjacent n-intersections
  List<String> adjacent = new ArrayList<>();
  adjacent.add(getPoint(n, x - 1, y));
  adjacent.add(getPoint(n, x + 1, y));
  adjacent.add(getPoint(n, x, y - 1));
  adjacent.add(getPoint(n, x, y + 1));

  // Return the list of adjacent n-intersections
  return adjacent;
}

