private static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || paths == null || start.length != 2 || end.length != 2 || paths.length == 0 || start[0] < 0 || start[1] < 0 || start[0] >= n || start[1] >= n || end[0] < 0 || end[1] < 0 || end[0] >= n || end[1] >= n) {
        return "cannot be travelled";
    }

    Set<int[]> visited = new HashSet<>();
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }
        if (visited.contains(current)) {
            continue;
        }
        visited.add(current);
        for (int[] path : paths) {
            if (current[0] == path[0] && path[1] == current[1] || current[0] == path[1] && path[0] == current[1] && !visited.contains(path)) {
                queue.offer(path);
            }
        }
    }

    return "cannot be travelled";
}

