    if (start.length != 2 || end.length != 2) {
        return "Invalid input";
    }
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n) {
        return "Invalid start";
    }
    if (end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "Invalid end";
    }

    // Check if the path array is valid
    if (paths.length != n - 1) {
        return "Invalid path array length";
    }
    for (int i = 0; i < paths.length; i++) {
        if (paths[i].length != 2) {
            return "Invalid path length";
        }
        if (paths[i][0] < 0 || paths[i][0] >= n || paths[i][1] < 0 || paths[i][1] >= n) {
            return "Invalid path coordinates";
        }
    }

    // If the starting and ending coordinates are the same, return "can be travelled"
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // If the starting and ending coordinates are not adjacent, return "cannot be travelled"
    if (Math.abs(start[0] - end[0]) + Math.abs(start[1] - end[1]) != 1) {
        return "cannot be travelled";
    }

    // If the path array is valid and the starting and ending coordinates are adjacent,
    // return "can be travelled" if the path array contains the path from the starting
    // coordinates to the ending coordinates, and "cannot be travelled" otherwise
    for (int i = 0; i < paths.length; i++) {
        if (paths[i][0] == start[0] && paths[i][1] == start[1]) {
            return "can be travelled";
        }
    }
    return "cannot be travelled";
