public double trimMean(int[] arr) {
    double mean = calculateMean(arr);
    int lowerBound = (int) Math.ceil(arr.length * 0.05);
    int upperBound = arr.length - (int) Math.ceil(arr.length * 0.05);
    int[] sortedArr = arrayCopy(arr);
    Arrays.sort(sortedArr);
    double lowerQuartile = calculateMean(sortedArr, 0, lowerBound);
    double upperQuartile = calculateMean(sortedArr, upperBound, sortedArr.length);
    int lowerOutlierIndex = sortedArr.length * 0.05;
    int lowerOutlier = (int) Math.ceil(sortedArr[lowerOutlierIndex] * 0.05);
    int upperOutlierIndex = sortedArr.length - 1 - (int) Math.ceil(sortedArr.length * 0.05);
    int upperOutlier = (int) Math.ceil(sortedArr[upperOutlierIndex] * 0.05);
    double lowerTrimMean = calculateMean(arr, 0, lowerOutlierIndex - lowerOutlier);
    double upperTrimMean = calculateMean(arr, upperOutlierIndex + upperOutlier, arr.length - 1);
    return (mean - lowerQuartile + lowerTrimMean) + (upperTrimMean - upperQuartile);
}

private double calculateMean(int[] arr) {
    double sum = 0;
    for (int num : arr) {
        sum += num;
    }
    return sum / arr.length;
}

private double calculateMean(int[] arr, int start, int end) {
    double sum = 0;
    for (int i = start; i <= end; i++) {
        sum += arr[i];
    }
    return sum / (end - start + 1);
}

private int[] arrayCopy(int[] arr) {
    int[] copy = new int[arr.length];
    for (int i = 0; i < arr.length; i++) {
        copy[i] = arr[i];
    }
    return copy;
}
