   // Find the largest 5% of elements
   int max = arr[n - 1];
   for (int i = n - 1; i > n - 1 - threshold; i--) {
       if (arr[i] > max) {
           max = arr[i];
       }
   }
   // Calculate the mean of the remaining elements
   double sum = 0;
   for (int i = 0; i < n; i++) {
       if (arr[i] > min && arr[i] < max) {
           sum += arr[i];
       }
   }
   return sum / ((n - threshold) - (n - threshold));
}

