    }
    if (sum % k != 0) {
        return false;
    }

    int[] pairs = new int[n / 2];
    for (int i = 0; i < n; i += 2) {
        pairs[i / 2] = arr[i] + arr[i + 1];
    }

    for (int pair : pairs) {
        if (pair % k != 0) {
            return false;
        }
    }
    return true;
