        return result;
    }

    // If the divisor is less than or equal to 0, return false
    if (k <= 0) {
        return result;
    }

    // Calculate the number of pairs that can be formed
    int numPairs = arr.length / 2;

    // Initialize a hash table to keep track of the divisors
    HashMap<Integer, Integer> divisors = new HashMap<>();

    // Iterate over the array and calculate the divisors
    for (int i = 0; i < arr.length; i++) {
        int divisor = arr[i] % k;
        if (divisors.containsKey(divisor)) {
            divisors.put(divisor, divisors.get(divisor) + 1);
        } else {
            divisors.put(divisor, 1);
        }
    }

    // Iterate over the hash table and check if the divisors are paired
    for (Map.Entry<Integer, Integer> entry : divisors.entrySet()) {
        // Check if the divisor is paired
        if (entry.getValue() % 2 == 0) {
            numPairs--;
        }
        // If the divisor is not paired, return false
        else {
            return result;
        }
    }

    // If all divisors are paired, return true
    if (numPairs == 0) {
        result = true;
    }

    // Return the result
    return result;
