public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a queue to store the nodes to visit and a set to keep track of visited nodes
    Queue<Integer> queue = new LinkedList<>();
    Set<Integer> visited = new HashSet<>();

    // Add the starting node to the queue and mark it as visited
    queue.add(0);
    visited.add(0);

    // Initialize a variable to store the minimum time required to collect all the apples
    int minTime = 0;

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the size of the current level
        int levelSize = queue.size();

        // Loop through the nodes in the current level
        for (int i = 0; i < levelSize; i++) {
            // Get the current node
            int node = queue.poll();

            // If the current node has an apple and it has not been collected, collect it
            if (hasApple[node] && !visited.contains(node)) {
                visited.add(node);
                minTime++;
            }

            // Add the unvisited neighbors of the current node to the queue
            for (int neighbor : edges[node]) {
                if (!visited.contains(neighbor)) {
                    queue.add(neighbor);
                }
            }
        }
    }

    // Return the minimum time required to collect all the apples
    return minTime;
}
