        char c = charArray[i];
        if (i == 0) {
            result += c;
        } else {
            for (int j = i - 1; j >= 0; j--) {
                if (charArray[j] > c) {
                    result += charArray[j];
                    break;
                }
            }
        }
        result += c;
        for (int j = i + 1; j < charArray.length; j++) {
            if (charArray[j] < c) {
                result += charArray[j];
                break;
            }
        }
    }
    return result;
