public int minOperations(int n) {
  int[] arr = new int[n];
  for (int i = 0; i < n; i++) {
    arr[i] = (2 * i) + 1;
  }

  int minOps = 0;
  while (!isEqual(arr)) {
    int[] equiv = findEquivalent(arr);
    for (int i = 1; i < equiv.length; i++) {
      equiv[i - 1] -= 1;
      equiv[i] += 1;
    }
    minOps++;
  }

  return minOps;
}

private boolean isEqual(int[] arr) {
  for (int i = 1; i < arr.length; i++) {
    if (arr[i] != arr[0]) {
      return false;
    }
  }
  return true;
}

private int[] findEquivalent(int[] arr) {
  int[] equiv = new int[arr.length];
  for (int i = 0; i < arr.length; i++) {
    equiv[i] = i;
  }
  boolean found = false;
  while (!found) {
    found = true;
    for (int i = 0; i < arr.length; i++) {
      if (i % 2 == 0 && arr[i] == arr[i + 1]) {
        equiv[i] = equiv[i + 1];
        found = false;
      } else if (i % 2 == 1 && arr[i] == arr[i - 1]) {
        equiv[i] = equiv[i - 1];
        found = false;
      }
    }
  }
  return equiv;
}

