public class GetSmallestString {
    /**
     * Returns the lexicographically smallest string of length n and value k.
     * The value of a string is the sum of the positions of its characters in the alphabet (starting from 1).
     *
     * @param n The length of the string.
     * @param k The value of the string.
     * @return The smallest string.
     */
    public static String getSmallestString(int n, int k) {
        char[] chars = new char[n];
        int index = 0;
        while (k > 0) {
            int position = k % 26;
            k = (k - position) / 26;
            chars[index++] = (char) (position + 'a' - 1);
        }
        return new String(chars);
    }
}

