      for (int j = 0; j < num.length() - 1; j++) {
        if (Integer.parseInt(num.charAt(j) + "") - Integer.parseInt(num.charAt(j + 1) + "") != 1 && Integer.parseInt(num.charAt(j + 1) + "") - Integer.parseInt(num.charAt(j) + "") != 1) {
          continue;
