    int n = mat[0].length; // cols
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int current = 0;
                // horizontal
                for (int k = j; k < n; k++) {
                    if (mat[i][k] == 0) break;
                    current++;
                }
                // vertical
                for (int k = i; k < m; k++) {
                    if (mat[k][j] == 0) break;
                    current++;
                }
                // diagonal
                for (int k = i, l = j; k < m && l < n; k++, l++) {
                    if (mat[k][l] == 0) break;
                    current++;
                }
                // anti-diagonal
                for (int k = i, l = j; k < m && l >= 0; k++, l--) {
                    if (mat[k][l] == 0) break;
                    current++;
                }
                max = Math.max(max, current);
            }
        }
    }
    return max;
}

