                int length = 1;
                boolean isHorizontal = true;
                boolean isVertical = true;
                while (i < m-1 && j < n-1) {
                    if (mat[i+1][j] == 1) {
                        i++;
                        length++;
                        isVertical = false;
                    } else if (mat[i][j+1] == 1) {
                        j++;
                        length++;
                        isHorizontal = false;
                    } else {
                        break;
                    }
                }
                if (isHorizontal) {
                    while (j < n-1) {
                        j++;
                        length++;
                    }
                } else if (isVertical) {
                    while (i < m-1) {
                        i++;
                        length++;
                    }
                }
                maxLength = Math.max(maxLength, length);
            }
        }
    }
    return maxLength;
}
