public static int squarePermutations(int[] A) {
    // Initialize the set of permutations to hold the final result
    Set<List<Integer>> permutations = new HashSet<>();

    // Sort the array A in ascending order to find adjacent pairs
    Arrays.sort(A);

    // Initialize the current permutation
    List<Integer> currentPermutation = new ArrayList<>();

    // Iterate through the array A and calculate the sum of adjacent pairs
    for (int i = 0; i < A.length; i++) {
        // If the sum of the current pair is a perfect square, add it to the current permutation
        if (i < A.length - 1 && (A[i] + A[i + 1]) % Math.sqrt(A[i] + A[i + 1]) == 0) {
            currentPermutation.add(A[i]);
            currentPermutation.add(A[i + 1]);
        }
    }

    // Add the current permutation to the set of permutations
    permutations.add(currentPermutation);

    // Iterate through the rest of the permutations
    for (int i = 1; i < A.length; i++) {
        // Create a new permutation by swapping the first two elements
        List<Integer> newPermutation = new ArrayList<>(currentPermutation);
        newPermutation.set(0, A[i]);
        newPermutation.set(1, A[0]);

        // Add the new permutation to the set of permutations if it's not already there
        if (!permutations.contains(newPermutation)) {
            permutations.add(newPermutation);
        }
    }

    // Return the size of the set of permutations
    return permutations.size();
}
