    public static int squarePermutations(int[] A) {
        int count = 0;
        for (int i = 0; i < A.length; i++) {
            if (isSquare(A[i])) {
                List<Integer> permutation = new ArrayList<>();
                for (int j = 0; j < A.length; j++) {
                    if (j != i) {
                        permutation.add(A[j]);
                    }
                }
                permutation.add(A[i]);
                if (isPermutation(permutation.toArray(new Integer[0]))) {
                    count++;
                }
            }
        }
        return count;
    }

    private static boolean isSquare(int n) {
        int x = (int)Math.sqrt(n);
        return x * x == n;
    }

    private static boolean isPermutation(int[] A) {
        int[] freq = new int[A.length];
        for (int n : A) {
            freq[n - 1]++;
        }
        for (int f : freq) {
            if (f != 1) {
                return false;
            }
        }
        return true;
    }
}
