public static int findSmallestInteger(int n) {
    int[] digits = new int[10];

    // Count the frequency of each digit in n
    for (int i = n; i > 0; i /= 10) {
        digits[i % 10]++;
    }

    // Find the largest digit <= smallest digit of n - 1
    int largest = -1;
    for (int i = 9; i >= 0; i--) {
        if (digits[i] > 0) {
            largest = i;
            break;
        }
    }

    // If largest is -1, then all digits are the same, and we cannot find a smaller integer
    if (largest == -1) {
        return -1;
    }

    // Find the smallest digit > largest
    int smallest = -1;
    for (int i = largest + 1; i < 10; i++) {
        if (digits[i] > 0) {
            smallest = i;
            break;
        }
    }

    // If smallest is -1, then no such integer exists
    if (smallest == -1) {
        return -1;
    }

    // Rearrange the digits to form the smallest integer
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i <= largest; i++) {
        sb.append(smallest);
    }
    for (int i = largest + 1; i < 10; i++) {
        sb.append(i);
    }

    return Integer.parseInt(sb.toString());
}

