public static boolean isBoomerang(int[][] points) {
   if (points.length != 3) {
       return false;
   }

   int[] xCoords = new int[3];
   int[] yCoords = new int[3];

   for (int i = 0; i < 3; i++) {
       xCoords[i] = points[i][0];
       yCoords[i] = points[i][1];
   }

   // Check if the three points are collinear
   if (xCoords[0] == xCoords[1] && xCoords[1] == xCoords[2] ||
       xCoords[1] == xCoords[2] && xCoords[2] == xCoords[0] ||
       xCoords[2] == xCoords[0] && xCoords[0] == xCoords[1]) {
       return false;
   }

   // Check if the three points are clockwise
   if (((yCoords[2] - yCoords[0]) * (xCoords[1] - xCoords[0])) >
           ((yCoords[1] - yCoords[0]) * (xCoords[2] - xCoords[0]))) {
       return false;
   }

   // If the three points are not collinear and are clockwise,
   // they form a boomerang
   return true;
