public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The input must be a positive integer.");
    }

    int[] uglyNumbers = new int[n];

    // Initialize the array with the first element
    uglyNumbers[0] = 1;

    int index2 = 0;
    int index3 = 0;
    int index5 = 0;

    for (int i = 1; i < n; i++) {
        int nextUglyNumber = Math.min(uglyNumbers[index2] * 2, Math.min(uglyNumbers[index3] * 3, uglyNumbers[index5] * 5));

        uglyNumbers[i] = nextUglyNumber;

        // Update the index of the smallest ugly number
        if (nextUglyNumber == uglyNumbers[index2] * 2) {
            index2++;
        }
        if (nextUglyNumber == uglyNumbers[index3] * 3) {
            index3++;
        }
        if (nextUglyNumber == uglyNumbers[index5] * 5) {
            index5++;
        }
    }

    return uglyNumbers[n - 1];
}

