public static int minPerfectSquareSum(int n) {
    int count = 0;
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            count++;
            while (n % i == 0) {
                n /= i;
            }
        }
    }
    if (n > 0) {
        count++;
    }
    return count;

public static int minPerfectSquareSum(int n) {
    // A map to store the number of perfect squares
    Map<Integer, Integer> perfectSquares = new HashMap<>();

    // Initialize the map with the number of perfect squares for 1 and 4
    perfectSquares.put(1, 1);
    perfectSquares.put(4, 1);

    // Iterate from 9 to 1 and calculate the number of perfect squares
    // that sum up to the current number
    for (int i = 9; i > 0; i--) {
        int count = 0;
        for (int j = 1; j * j <= i; j++) {
            if (perfectSquares.containsKey(i - j * j)) {
                count += perfectSquares.get(i - j * j);
            }
        }
        perfectSquares.put(i, count);
    }

    // Return the number of perfect squares that sum up to n
    return perfectSquares.get(n);
}

