public static int minPerfectSquareSum(int n) {
    // Initialize a hash map to map each perfect square number to its count
    Map<Integer, Integer> squareCounts = new HashMap<>();
    // Initialize a variable to keep track of the minimum number of perfect square numbers
    int minCount = 0;

    // Loop through the range of perfect square numbers
    for (int i = 1; i * i <= n; i++) {
        // If the square of the current number is less than or equal to the target number
        if (i * i <= n) {
            // Increment the count of the current number in the hash map
            squareCounts.put(i, squareCounts.getOrDefault(i, 0) + 1);
            // Keep track of the minimum number of perfect square numbers
            minCount = Math.min(minCount, squareCounts.get(i));
        }
    }

    // Return the minimum number of perfect square numbers
    return minCount;
}
