public class MinimumPerfectSquareSum {
  public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
      return 0;
    }
    int minSquares = 0;
    int currentSum = 0;
    for (int i = 1; i * i <= n; i++) {
      currentSum += i * i;
      if (currentSum > n) {
        minSquares++;
        currentSum = i * i;
      }
    }
    if (currentSum == n) {
      minSquares++;
    }
    return minSquares;
  }
}

